type FaultDossier = {
  recordNumber?: string;
  status?: string;
  priority?: string;
  faultType?: string;
  title?: string;
  description?: string;
  source?: string;
  recordedBy?: {
    userId?: string;
    name?: string;
    role?: string;
    deviceId?: string;
  };
  timestamps?: {
    recordedAt?: string;
    givenAt?: string;
    assignedAt?: string;
    crewArrivedAt?: string;
    completedAt?: string;
    deliveredAt?: string;
    approvedAt?: string;
  };
  location?: {
    areaLabel?: string;
    roadLabel?: string;
    zoneLabel?: string;
