    .filter((item) => {
      const sameToken = item.actor.deviceTokenHash === tokenHash;
      const sameDevice = deviceId ? item.actor.deviceId === deviceId : true;
      return sameToken && sameDevice;
    })
    .map(publicEvent)
    .sort((a, b) => String(a.createdAt).localeCompare(String(b.createdAt)));
}

